{
  "root_causes": [
    {
      "service": "ts-order-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, attr_k8s_pod_name AS pod, min(value) AS min_restarts, max(value) AS max_restarts FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-order-service%' GROUP BY 1,2", "claim": "ts-order-service pod restarted once during the abnormal window; normal window showed zero restarts."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code AS status, count(*) AS n FROM abnormal_traces WHERE service_name='ts-security-service' AND attr_span_kind='Client' AND attr_status_code='Error' GROUP BY 1,2,3", "claim": "Security-service outbound GET calls failed with 503 'connection refused' and no child spans, at the order-service restart time."},
        {"kind": "log", "sql": "SELECT service_name, level, count(*) AS n FROM abnormal_logs WHERE service_name IN ('ts-seat-service','ts-security-service') AND message LIKE '%Connection refused%' GROUP BY 1,2", "claim": "Seat and security services logged SEVERE 503 errors caused by 'Connection refused' from an upstream dependency."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-order-service", "to": "ts-security-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, sum((c.attr_status_code='Error')::int) AS client_errors FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-security-service' AND s.service_name='ts-order-service' GROUP BY 1,2", "claim": "Security-service calls to order-service show failed client spans during the restart window."}]},
    {"from": "ts-security-service", "to": "ts-seat-service", "evidence": [{"kind": "trace", "sql": "SELECT s.service_name AS caller, c.service_name AS callee, count(*) AS n, sum((c.attr_status_code='Error')::int) AS errs FROM abnormal_traces c JOIN abnormal_traces s ON s.span_id=c.parent_span_id AND s.trace_id=c.trace_id WHERE s.service_name='ts-seat-service' AND c.service_name='ts-security-service' AND c.attr_span_kind='Server' GROUP BY 1,2", "claim": "Seat-service calls to security-service's check endpoint return errors and high latency (about 19% errors)."}]},
    {"from": "ts-seat-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, round(avg(s.duration)/1e6,1) AS callee_ms, round(avg((s.attr_status_code='Error')::int),3) AS err FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND s.service_name='ts-seat-service' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "Preserve-service calls to seat-service return about 19% errors at 150ms average, versus 14ms normally."}]},
    {"from": "ts-seat-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, round(avg(s.duration)/1e6,1) AS callee_ms, round(avg((s.attr_status_code='Error')::int),3) AS err FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-service' AND s.service_name='ts-seat-service' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "Travel-service calls to seat-service show 13% errors and slow responses during the incident."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, round(avg(s.duration)/1e6,1) AS callee_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "Route-plan calls to travel-service slow to about 190ms average, versus 50ms or less normally."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, round(avg(s.duration)/1e6,1) AS callee_ms, round(quantile_cont(s.duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "Travel-plan calls to route-plan take about 700ms average and 1.8s p95 in the abnormal window."}]},
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT s.service_name, s.span_name, count(*) AS n, sum((s.attr_status_code='Error')::int) AS errs FROM abnormal_traces s WHERE s.service_name='ts-ui-dashboard' AND s.attr_span_kind='Server' GROUP BY 1,2", "claim": "Ui-dashboard server spans show about 3% errors and 500-690ms latency in the early incident minutes."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) AS n, round(avg(duration)/1e6,1) AS ms, sum((attr_status_code='Error')::int) AS errs FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY n DESC", "claim": "User-facing ui-dashboard requests, including travel-plan paths, show elevated latency and 503 errors in the incident window."}]}
  ]
}
